            return SystemResult.Failure;
        }

        var exprTerm = call.Args[0];
        var resultTerm = call.Args[1];
        Console.Out.WriteLine($"[EVALUATE] ExprTerm: {exprTerm} ({exprTerm?.GetType().Name})");
        Console.Out.WriteLine($"[EVALUATE] ResultTerm: {resultTerm} ({resultTerm?.GetType().Name})");

        var unboundReaders = new HashSet<long>();
        bool hasUnboundWriter = false;

        void CollectUnbound(object? term)
        {
            if (term is VarRef wRef && rt.Heap.IsWriter(wRef.Addr))
            {
