                    var value = rt.Heap.GetReaderValue(rid);
                    if (value != null) CollectUnbound(value);
                }
            }
            else if (term is StructTerm st)
            {
                foreach (var arg in st.Args)
                    CollectUnbound(arg);
            }
        }

        CollectUnbound(exprTerm);

        if (hasUnboundWriter)
            return SystemResult.Failure;

        if (unboundReaders.Count > 0)
        {
            foreach (var rid in unboundReaders)
                call.SuspendedReaders.Add(rid);
            return SystemResult.Suspend;
        }

        Console.Out.WriteLine("[EVALUATE] Expression is ground, evaluating...");
        var result = Evaluate(rt, exprTerm);
        Console.Out.WriteLine($"[EVALUATE] Computed result: {result} ({result?.GetType().Name})");
        if (result == null)
        {
            Console.Out.WriteLine("[EVALUATE] Evaluation failed - returning failure");
            return SystemResult.Failure;
