                if (result is Term t)
                {
                    rt.Heap.BindVariable(wid, t);
                    Console.Out.WriteLine($"[EVALUATE] Called BindVariable({wid}, {result})");
                }
                else
                {
                    rt.Heap.BindWriterConst(wid, result);
                    Console.Out.WriteLine($"[EVALUATE] Called BindWriterConst({wid}, {result})");
                }
            }
            Console.Out.WriteLine("[EVALUATE] Checking if binding persisted...");
            bool bound = rt.Heap.IsWriterBound(wid);
            Console.Out.WriteLine($"[EVALUATE] Writer {wid} bound after call: {bound}");
            if (bound)
