                Console.Out.WriteLine($"[EVALUATE] Writer {wid} value: {value}");
            }
            Console.Out.WriteLine("[EVALUATE] Returning SUCCESS");
            return SystemResult.Success;
        }
        else if (resultTerm is VarRef rdRef && rt.Heap.IsReader(rdRef.Addr))
        {
            int rid = rdRef.Addr;
            if (!rt.Heap.IsReaderBound(rid))
                return SystemResult.Failure;
            var readerValue = rt.Heap.GetReaderValue(rid);
