    /// <summary>file_read_handle/2: Read remaining bytes from open file handle as UTF-8 string.</summary>
    public static SystemResult FileReadHandlePredicate(GlpRuntimeEngine rt, SystemCall call)
    {
        if (call.Args.Count != 2)
        {
            Console.Error.WriteLine($"[ERROR] file_read_handle/2 requires exactly 2 arguments, got {call.Args.Count}");
            return SystemResult.Failure;
