        if (!TryExtractInt(call, 0, rt, out var handleLong, out var er)) return er;
        if (handleLong == null) { Console.Error.WriteLine("[ERROR] file_read_handle/2: handle must be an integer"); return SystemResult.Failure; }
        int handle = (int)handleLong.Value;
        var file = rt.GetFile(handle);
        if (file == null) { Console.Error.WriteLine($"[ERROR] file_read_handle/2: invalid file handle: {handle}"); return SystemResult.Failure; }

        string contents;
        try
        {
            long length = file.Length;
            long position = file.Position;
            long remaining = length - position;
            if (remaining <= 0) { contents = ""; }
            else
            {
                var bytes = new byte[remaining];
                int read = file.Read(bytes, 0, (int)remaining);
                contents = Encoding.UTF8.GetString(bytes, 0, read);
            }
        }
        catch (Exception ex) { Console.Error.WriteLine($"[ERROR] file_read_handle/2: Failed to read from handle {handle}: {ex.Message}"); return SystemResult.Failure; }
        return BindOrVerifyConst(rt, call.Args[1], contents);
    }

