            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); return SystemResult.Suspend; }
            var value = rt.Heap.GetReaderValue(rid);
            if (value is ConstTerm cv && cv.Value is string sv) filePath = sv;
        }
        else if (fileNameTerm is VarRef fnWr && rt.Heap.IsWriter(fnWr.Addr))
        {
            int wid = fnWr.Addr;
            if (!rt.Heap.IsWriterBound(wid)) { Console.Error.WriteLine("[ERROR] load_module/2: FileName writer is unbound"); return SystemResult.Failure; }
            var value = rt.Heap.GetValue(wid);
            if (value is ConstTerm cv && cv.Value is string sv) filePath = sv;
        }

        if (filePath == null) { Console.Error.WriteLine("[ERROR] load_module/2: Could not extract filename"); return SystemResult.Failure; }

        try
        {
            if (!File.Exists(filePath)) { Console.Error.WriteLine($"[ERROR] load_module/2: File not found: {filePath}"); return SystemResult.Failure; }
            var contents = File.ReadAllText(filePath, Encoding.UTF8);
            var module = new Dictionary<string, object?>
            {
                ["path"] = filePath,
                ["contents"] = contents,
                ["loaded_at"] = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            };
            if (moduleTerm is VarRef mWrt && rt.Heap.IsWriter(mWrt.Addr))
            {
                int wid = mWrt.Addr;
                if (rt.Heap.IsWriterBound(wid)) { Console.Error.WriteLine("[WARN] load_module/2: Module writer already bound, cannot verify"); return SystemResult.Failure; }
                rt.Heap.BindWriterConst(wid, module);
                return SystemResult.Success;
            }
            else if (moduleTerm is ConstTerm) { Console.Error.WriteLine("[WARN] load_module/2: Cannot verify against constant module"); return SystemResult.Failure; }
            Console.Error.WriteLine("[ERROR] load_module/2: Module must be writer or constant");
            return SystemResult.Failure;
        }
        catch (Exception ex) { Console.Error.WriteLine($"[ERROR] load_module/2: Failed to load module: {ex.Message}"); return SystemResult.Failure; }
    }

    /// <summary>distribute_stream/2: Deep-copy input value to each output writer (1-to-N).</summary>
    public static SystemResult DistributeStreamPredicate(GlpRuntimeEngine rt, SystemCall call)
    {
        if (call.Args.Count != 2)
        {
            Console.Error.WriteLine($"[ERROR] distribute_stream/2 requires exactly 2 arguments, got {call.Args.Count}");
            return SystemResult.Failure;
        }
        var inputTerm = call.Args[0];
        var outputListTerm = call.Args[1];

        object? inputValue;
        if (inputTerm is ConstTerm inCt) inputValue = inCt.Value;
        else if (inputTerm is VarRef inRd && rt.Heap.IsReader(inRd.Addr))
        {
            int rid = inRd.Addr;
            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); return SystemResult.Suspend; }
            var value = rt.Heap.GetReaderValue(rid);
            inputValue = value is ConstTerm cv ? cv.Value : (object?)value;
        }
        else if (inputTerm is VarRef inWr && rt.Heap.IsWriter(inWr.Addr))
        {
            int wid = inWr.Addr;
            if (!rt.Heap.IsWriterBound(wid)) { Console.Error.WriteLine("[ERROR] distribute_stream/2: Input writer is unbound"); return SystemResult.Failure; }
            var value = rt.Heap.GetValue(wid);
            inputValue = value is ConstTerm cv ? cv.Value : (object?)value;
        }
        else inputValue = inputTerm;

        List<int>? outputWriters = null;
        if (outputListTerm is ConstTerm outCt && outCt.Value is System.Collections.IList outList)
        {
            outputWriters = new List<int>();
            foreach (var item in outList)
            {
                if (item is VarRef itemRef && rt.Heap.IsWriter(itemRef.Addr)) outputWriters.Add(itemRef.Addr);
                else if (item is int intItem) outputWriters.Add(intItem);
                else { Console.Error.WriteLine($"[ERROR] distribute_stream/2: OutputList contains non-writer: {item}"); return SystemResult.Failure; }
            }
        }
        else { Console.Error.WriteLine("[ERROR] distribute_stream/2: OutputList must be list of writers"); return SystemResult.Failure; }

        foreach (int wid in outputWriters)
        {
            if (rt.Heap.IsWriterBound(wid)) { Console.Error.WriteLine($"[ERROR] distribute_stream/2: Output writer {wid} already bound"); return SystemResult.Failure; }
            rt.Heap.BindWriterConst(wid, DeepCopyValue(inputValue));
        }
        return SystemResult.Success;
    }

    /// <summary>copy_term/3: Create two independent deep copies of a term.</summary>
    public static SystemResult CopyTermMultiPredicate(GlpRuntimeEngine rt, SystemCall call)
    {
        if (call.Args.Count != 3)
        {
            Console.Error.WriteLine($"[ERROR] copy_term/3 requires exactly 3 arguments, got {call.Args.Count}");
            return SystemResult.Failure;
        }
        var termArg = call.Args[0];
        var copy1Arg = call.Args[1];
        var copy2Arg = call.Args[2];

        object? sourceValue;
        if (termArg is ConstTerm srcCt) sourceValue = srcCt.Value;
        else if (termArg is VarRef srcRd && rt.Heap.IsReader(srcRd.Addr))
        {
            int rid = srcRd.Addr;
            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); return SystemResult.Suspend; }
            var value = rt.Heap.GetReaderValue(rid);
            sourceValue = value is ConstTerm cv ? cv.Value : (object?)value;
        }
        else if (termArg is VarRef srcWr && rt.Heap.IsWriter(srcWr.Addr))
        {
            int wid = srcWr.Addr;
            if (!rt.Heap.IsWriterBound(wid)) { Console.Error.WriteLine("[ERROR] copy_term/3: Source writer is unbound"); return SystemResult.Failure; }
            var value = rt.Heap.GetValue(wid);
            sourceValue = value is ConstTerm cv ? cv.Value : (object?)value;
        }
        else sourceValue = termArg;

        int? w1 = null, w2 = null;
        if (copy1Arg is VarRef c1Ref && rt.Heap.IsWriter(c1Ref.Addr)) w1 = c1Ref.Addr;
        else { Console.Error.WriteLine("[ERROR] copy_term/3: Copy1 must be writer"); return SystemResult.Failure; }
        if (copy2Arg is VarRef c2Ref && rt.Heap.IsWriter(c2Ref.Addr)) w2 = c2Ref.Addr;
        else { Console.Error.WriteLine("[ERROR] copy_term/3: Copy2 must be writer"); return SystemResult.Failure; }
        if (rt.Heap.IsWriterBound(w1.Value)) { Console.Error.WriteLine("[ERROR] copy_term/3: Copy1 writer already bound"); return SystemResult.Failure; }
        if (rt.Heap.IsWriterBound(w2.Value)) { Console.Error.WriteLine("[ERROR] copy_term/3: Copy2 writer already bound"); return SystemResult.Failure; }

        rt.Heap.BindWriterConst(w1.Value, DeepCopyValue(sourceValue));
        rt.Heap.BindWriterConst(w2.Value, DeepCopyValue(sourceValue));
        return SystemResult.Success;
    }

    // -- Private Helpers -------------------------------------------------------

    /// <summary>
    /// Recursive arithmetic evaluator. Dispatches on StructTerm functor (10 arms).
    /// Returns null on type mismatch / div-by-zero / unknown operator / unbound var.
    /// </summary>
    private static object? Evaluate(GlpRuntimeEngine rt, object? term)
    {
        if (term is VarRef wRef && rt.Heap.IsWriter(wRef.Addr))
        {
            if (!rt.Heap.IsWriterBound(wRef.Addr)) return null;
            return Evaluate(rt, rt.Heap.GetValue(wRef.Addr));
        }
        if (term is VarRef rRef && rt.Heap.IsReader(rRef.Addr))
        {
            if (!rt.Heap.IsReaderBound(rRef.Addr)) return null;
            return Evaluate(rt, rt.Heap.GetReaderValue(rRef.Addr));
        }
        if (term is ConstTerm ct) return Evaluate(rt, ct.Value);
        if (term is int || term is double || term is long) return term;

        if (term is StructTerm st)
        {
            string functor = st.Functor;
            var args = st.Args;
            switch (functor)
            {
                case "+":   if (args.Count==2 && Evaluate(rt,args[0]) is double la && Evaluate(rt,args[1]) is double ra) return la+ra; break;
                case "-":   if (args.Count==2 && Evaluate(rt,args[0]) is double lb && Evaluate(rt,args[1]) is double rb) return lb-rb; break;
                case "*":   if (args.Count==2 && Evaluate(rt,args[0]) is double lc && Evaluate(rt,args[1]) is double rc) return lc*rc; break;
                case "/":   if (args.Count==2 && Evaluate(rt,args[0]) is double ld && Evaluate(rt,args[1]) is double rd) { if(rd==0.0) return null; return ld/rd; } break;
                case "mod": if (args.Count==2 && Evaluate(rt,args[0]) is long li  && Evaluate(rt,args[1]) is long ri)   { if(ri==0L)  return null; return li%ri; } break;
                case "<":   if (args.Count==2 && Evaluate(rt,args[0]) is double le && Evaluate(rt,args[1]) is double re) return le<re;  break;
                case ">":   if (args.Count==2 && Evaluate(rt,args[0]) is double lf && Evaluate(rt,args[1]) is double rf) return lf>rf;  break;
                case "=<":  if (args.Count==2 && Evaluate(rt,args[0]) is double lg && Evaluate(rt,args[1]) is double rg) return lg<=rg; break;
                case ">=":  if (args.Count==2 && Evaluate(rt,args[0]) is double lh && Evaluate(rt,args[1]) is double rh) return lh>=rh; break;
                case "=":   if (args.Count==2 && Evaluate(rt,args[0]) is double li2&& Evaluate(rt,args[1]) is double ri2) return li2==ri2; break;
                default: return null;
            }
        }
        return null;
    }

    /// <summary>Cycle-aware deep copy for terms. visited keyed by VarRef.Addr (as long).</summary>
    private static object? DeepCopyTerm(object? term, GlpRuntimeEngine rt, Dictionary<long, object?> visited)
    {
        if (term == null) return null;
        if (term is ConstTerm || term is double || term is long || term is string) return term;

        if (term is VarRef varRef)
        {
            long varId = (long)varRef.Addr;
            if (visited.ContainsKey(varId)) return visited[varId];
            object? value;
            if (rt.Heap.IsReader(varRef.Addr))
            {
                if (!rt.Heap.IsReaderBound(varRef.Addr)) return term;
                value = rt.Heap.GetReaderValue(varRef.Addr);
            }
            else
            {
                if (!rt.Heap.IsWriterBound(varRef.Addr)) return term;
                value = rt.Heap.GetValue(varRef.Addr);
            }
            visited[varId] = null;
            var copiedValue = DeepCopyTerm(value, rt, visited);
            visited[varId] = copiedValue;
            return copiedValue;
        }

        if (term is StructTerm st)
        {
            var copiedArgs = new List<Term>();
            foreach (var arg in st.Args)
            {
                var copied = DeepCopyTerm(arg, rt, visited);
                if (copied is Term t) copiedArgs.Add(t);
                else if (copied != null) copiedArgs.Add(new ConstTerm(copied));
                else copiedArgs.Add(new ConstTerm(null));
            }
            return new StructTerm(st.Functor, copiedArgs);
        }
        return term;
    }

    /// <summary>Shallow-recursive deep copy over List/Map/Set. Shares primitives. No cycle detection.</summary>
    private static object? DeepCopyValue(object? value)
    {
        if (value == null) return null;
        if (value is List<object?> list) return list.Select(DeepCopyValue).ToList();
        if (value is Dictionary<object, object?> map) return map.ToDictionary(kv => kv.Key, kv => DeepCopyValue(kv.Value));
        if (value is HashSet<object?> set) return new HashSet<object?>(set.Select(DeepCopyValue));
        if (value is string || value is double || value is long || value is int || value is bool) return value;
        return value;
    }

    // -- Consolidation Helpers — emitted once, called 14+/12+ times -----------

    private static bool TryExtractString(SystemCall call, int argIndex, GlpRuntimeEngine rt,
        out string? value, out SystemResult earlyReturn)
    {
        value = null; earlyReturn = SystemResult.Failure;
        var term = call.Args[argIndex];
        if (term is ConstTerm ct && ct.Value is string s) { value = s; return true; }
        if (term is VarRef wRef && rt.Heap.IsWriter(wRef.Addr))
        {
            int wid = wRef.Addr;
            if (!rt.Heap.IsWriterBound(wid)) return false;
            var v = rt.Heap.GetValue(wid);
            if (v is ConstTerm cv && cv.Value is string sv) { value = sv; return true; }
            return false;
        }
        if (term is VarRef rRef && rt.Heap.IsReader(rRef.Addr))
        {
            int rid = rRef.Addr;
            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); earlyReturn = SystemResult.Suspend; return false; }
            var v = rt.Heap.GetReaderValue(rid);
            if (v is ConstTerm cv && cv.Value is string sv) { value = sv; return true; }
            return false;
        }
        return false;
    }

    private static bool TryExtractInt(SystemCall call, int argIndex, GlpRuntimeEngine rt,
        out long? value, out SystemResult earlyReturn)
    {
        value = null; earlyReturn = SystemResult.Failure;
        var term = call.Args[argIndex];
        static long? AsLong(object? v) => v switch { int i => (long)i, long l => l, _ => null };
        if (term is ConstTerm ct) { var l = AsLong(ct.Value); if (l != null) { value = l; return true; } return false; }
        if (term is VarRef wRef && rt.Heap.IsWriter(wRef.Addr))
        {
            int wid = wRef.Addr;
            if (!rt.Heap.IsWriterBound(wid)) return false;
            var v = rt.Heap.GetValue(wid);
            if (v is ConstTerm cv) { var l = AsLong(cv.Value); if (l != null) { value = l; return true; } }
            return false;
        }
        if (term is VarRef rRef && rt.Heap.IsReader(rRef.Addr))
        {
            int rid = rRef.Addr;
            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); earlyReturn = SystemResult.Suspend; return false; }
            var v = rt.Heap.GetReaderValue(rid);
            if (v is ConstTerm cv) { var l = AsLong(cv.Value); if (l != null) { value = l; return true; } }
            return false;
        }
        return false;
    }

    private static bool TryExtractTerm(SystemCall call, int argIndex, GlpRuntimeEngine rt,
        out object? value, out SystemResult earlyReturn)
    {
        value = null; earlyReturn = SystemResult.Failure;
        var term = call.Args[argIndex];
        if (term is ConstTerm) { value = term; return true; }
        if (term is VarRef wRef && rt.Heap.IsWriter(wRef.Addr))
        {
            int wid = wRef.Addr;
            if (!rt.Heap.IsWriterBound(wid)) return false;
            value = rt.Heap.GetValue(wid); return true;
        }
        if (term is VarRef rRef && rt.Heap.IsReader(rRef.Addr))
        {
            int rid = rRef.Addr;
            if (!rt.Heap.IsReaderBound(rid)) { call.SuspendedReaders.Add((long)rid); earlyReturn = SystemResult.Suspend; return false; }
            value = rt.Heap.GetReaderValue(rid); return true;
        }
        value = term; return true;
    }

    private static SystemResult BindOrVerifyConst(GlpRuntimeEngine rt, object? outputTerm, object? bindValue)
    {
        if (outputTerm is VarRef wrtRef && rt.Heap.IsWriter(wrtRef.Addr))
        {
            int wid = wrtRef.Addr;
            if (rt.Heap.IsWriterBound(wid))
            {
                var existing = rt.Heap.GetValue(wid);
                bool matches = (existing is ConstTerm c && Equals(c.Value, bindValue)) || Equals(existing, bindValue);
                return matches ? SystemResult.Success : SystemResult.Failure;
            }
            rt.Heap.BindWriterConst(wid, bindValue);
            return SystemResult.Success;
        }
        if (outputTerm is ConstTerm ct)
            return Equals(ct.Value, bindValue) ? SystemResult.Success : SystemResult.Failure;
        return SystemResult.Failure;
    }

    private static SystemResult BindOrVerifyTerm(GlpRuntimeEngine rt, int wid, Term term)
    {
        if (rt.Heap.IsWriterBound(wid))
            return Equals(rt.Heap.GetValue(wid), term) ? SystemResult.Success : SystemResult.Failure;
        rt.Heap.BindVariable(wid, term);
        return SystemResult.Success;
    }
}
